// An address as lwIP stores it (first octet in the low byte).
static uint32_t ip4(uint8_t a, uint8_t b, uint8_t c, uint8_t d) {
  return uint32_t(a) | (uint32_t(b) << 8) | (uint32_t(c) << 16) | (uint32_t(d) << 24);
}

static const char* kDev = "00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff";
static const char* kLan = "000102030405060708090a0b0c0d0e0f";

static void testPairValidation() {
  CHECK(validPairBody("Home", "hunter22", kDev, kLan));
  CHECK(validPairBody("H", "", kDev, kLan));                             // an open network
  CHECK(validPairBody(std::string(32, 's').c_str(), std::string(63, 'p').c_str(), kDev, kLan));
  CHECK(validPairBody("Home", "00112233445566778899aabbccddeeff00112233445566778899AABBCCDDEEFF", kDev, kLan));
  // SSID: empty or over 32 bytes.
  CHECK(!validPairBody("", "hunter22", kDev, kLan));
  CHECK(!validPairBody(std::string(33, 's').c_str(), "hunter22", kDev, kLan));
  // Wi-Fi key: 1-7, 64 non-hex, over 64.
  CHECK(!validPairBody("Home", "short", kDev, kLan));
  CHECK(!validPairBody("Home", std::string(64, 'z').c_str(), kDev, kLan));
  CHECK(!validPairBody("Home", std::string(65, 'a').c_str(), kDev, kLan));
  // Keys: exact length, lowercase hex only.
  CHECK(!validPairBody("Home", "hunter22", "00", kLan));
  CHECK(!validPairBody("Home", "hunter22", kDev, "000102030405060708090a0b0c0d0e0"));
  CHECK(!validPairBody("Home", "hunter22", kDev, "000102030405060708090a0b0c0d0e0f0"));
  CHECK(!validPairBody("Home", "hunter22", kDev, "000102030405060708090A0B0C0D0E0F"));
  CHECK(!validPairBody("Home", "hunter22", std::string(64, 'g').c_str(), kLan));
  CHECK(!validPairBody(nullptr, "hunter22", kDev, kLan));
  CHECK(!validPairBody("Home", "hunter22", nullptr, kLan));
  // Body size: 1..1024.
  CHECK(!pairBodySizeOk(0));
  CHECK(pairBodySizeOk(1));
  CHECK(pairBodySizeOk(1024));
  CHECK(!pairBodySizeOk(1025));
}

static void testPairConflict() {
  char storedLan[33], storedDev[65];
  std::strcpy(storedLan, kLan);
  std::strcpy(storedDev, kDev);
  // A new light pairs with anyone on its hotspot.
  CHECK(!pairConflicts(false, "", "", kLan, kDev));
  // The wrong-password retry: same phone, same keys.
  CHECK(!pairConflicts(true, storedLan, storedDev, kLan, kDev));
  // A member or Sync (k_lan, but not k_dev), a stranger (neither), or a mix: 409.
  const std::string otherDev(64, 'a'), otherLan(32, 'b');
  CHECK(pairConflicts(true, storedLan, storedDev, kLan, otherDev.c_str()));
  CHECK(pairConflicts(true, storedLan, storedDev, otherLan.c_str(), kDev));
  CHECK(pairConflicts(true, storedLan, storedDev, otherLan.c_str(), otherDev.c_str()));
  // One differing nibble anywhere in either key.
  for (size_t i = 0; i < 64; i++) {
    std::string d(kDev);
    d[i] = d[i] == 'f' ? 'e' : 'f';
    CHECK(pairConflicts(true, storedLan, storedDev, kLan, d.c_str()));
    if (i < 32) {
      std::string l(kLan);
      l[i] = l[i] == 'f' ? 'e' : 'f';
      CHECK(pairConflicts(true, storedLan, storedDev, l.c_str(), kDev));
    }
  }
}

static void testHotspotSubnet() {
  CHECK(onHotspotSubnet(ip4(4, 3, 2, 1)));
  CHECK(onHotspotSubnet(ip4(4, 3, 2, 254)));
  CHECK(!onHotspotSubnet(ip4(4, 3, 3, 1)));
  CHECK(!onHotspotSubnet(ip4(192, 168, 1, 20)));
  CHECK(!onHotspotSubnet(ip4(1, 2, 3, 4)));      // the octets in the wrong order
  CHECK(!onHotspotSubnet(0));
}

static void testLeases() {
  const uint32_t sync = ip4(192, 168, 1, 21), app = ip4(192, 168, 1, 20);
  // Granted, capped at 120 s, expired exactly on time.
  {
    LeaseTable t;
    CHECK(!t.allowed(sync, 1000));
    t.grant(sync, 60, 1000);
    CHECK(t.allowed(sync, 1000));
    CHECK(t.allowed(sync, 60999));
    CHECK(!t.allowed(sync, 61000));
    CHECK(!t.allowed(app, 2000));                  // only the leaseholder
    t.grant(sync, 100000, 70000);
    CHECK(t.allowed(sync, 70000 + 119999));
    CHECK(!t.allowed(sync, 70000 + 120000));
  }
  // Renewal keeps one slot; release frees it; a negative request is a release; 0.0.0.0 never.
  {
    LeaseTable t;
    for (uint32_t now = 0; now < 600000; now += 20000) t.grant(sync, 60, now);
    CHECK(t.allowed(sync, 600000));
    t.grant(sync, 0, 600001);
    CHECK(!t.allowed(sync, 600002));
    t.grant(sync, 30, 700000);
    t.grant(sync, -5, 700001);
    CHECK(!t.allowed(sync, 700002));
    t.grant(0, 60, 700000);
    CHECK(!t.allowed(0, 700001));
  }
  // Four holders fit; a fifth takes the lease ending soonest, never a live one ending later.
  {
    LeaseTable t;
    const uint32_t h[5] = {ip4(10, 0, 0, 1), ip4(10, 0, 0, 2), ip4(10, 0, 0, 3), ip4(10, 0, 0, 4), ip4(10, 0, 0, 5)};
    t.grant(h[0], 100, 0);
    t.grant(h[1], 30, 0);                           // ends soonest
    t.grant(h[2], 110, 0);
    t.grant(h[3], 120, 0);
    for (int i = 0; i < 4; i++) CHECK(t.allowed(h[i], 1000));
    t.grant(h[4], 60, 1000);
    CHECK(t.allowed(h[4], 1000));
    CHECK(!t.allowed(h[1], 1000));                  // evicted
    CHECK(t.allowed(h[0], 1000) && t.allowed(h[2], 1000) && t.allowed(h[3], 1000));
  }
  // An expired slot is reused before any live one is evicted.
  {
    LeaseTable t;
    for (uint8_t i = 1; i <= 4; i++) t.grant(ip4(10, 0, 0, i), i == 3 ? 5 : 120, 0);
    t.grant(ip4(10, 0, 0, 9), 60, 10000);           // 10.0.0.3 expired at 5 s
    for (uint8_t i : {1, 2, 4, 9}) CHECK(t.allowed(ip4(10, 0, 0, i), 10000));
  }
  // A releasing stranger removes nothing.
  {
    LeaseTable t;
    t.grant(sync, 60, 0);
    t.grant(app, 0, 10);
    CHECK(t.allowed(sync, 20));
  }
  // Across the millis() wrap: a lease granted just before it lasts its full time.
  {
    LeaseTable t;
    const uint32_t now = 0xFFFFFFFFu - 5000u;
    t.grant(sync, 60, now);
    CHECK(t.allowed(sync, now + 59999u));
    CHECK(!t.allowed(sync, now + 60000u));
  }
}

// ---------------------------------------------------------------------------------------------
// PATH_AND_QUERY: exact when nothing was decoded, refused otherwise.
// ---------------------------------------------------------------------------------------------
struct P { const char* name; const char* value; bool skip; };
static bool pq(const char* path, std::vector<P> params, std::string& out) {
  return buildPathAndQuery(out, path, params.size(), [&params](size_t i) {
    return QueryParam{params[i].name, params[i].value, params[i].skip};
  });
}

static void testPathAndQuery() {
  std::string out;
  CHECK(pq("/json/state", {}, out) && out == "/json/state");
  CHECK(pq("/json/state", {{"v", "1", false}}, out) && out == "/json/state?v=1");
  CHECK(pq("/json", {{"a", "1", false}, {"b", "x.y_z~-", false}}, out) && out == "/json?a=1&b=x.y_z~-");
  CHECK(pq("/json", {{"flag", "", false}}, out) && out == "/json?flag=");       // "?flag" signs as this
  // POST fields and files are not part of the request line.
  CHECK(pq("/json", {{"body", "x", true}, {"v", "1", false}}, out) && out == "/json?v=1");
  // Anything the server percent-decoded cannot be rebuilt byte for byte: refused.
  CHECK(!pq("/json/st ate", {}, out));
  CHECK(!pq("/json/%73tate", {}, out));
  CHECK(!pq("/json", {{"v", "a b", false}}, out));
  CHECK(!pq("/json", {{"v", "a+b", false}}, out));
  CHECK(!pq("/json", {{"v", "a&b=c", false}}, out));
  CHECK(!pq("/json", {{"v/x", "1", false}}, out));                             // '/' only in the path
  CHECK(!pq("/json", {{"v", "\xc3\xa9", false}}, out));                        // UTF-8, decoded
  CHECK(!pq(nullptr, {}, out));
  CHECK(unreserved("/json/pixc/pair", true));
  CHECK(!unreserved("/json/pixc/pair", false));
}

static void testSanitizeLanCfg() {
  DynamicJsonDocument doc(2048);
  CHECK(!deserializeJson(doc, R"({
    "id":{"name":"Desk"},
    "if":{"mqtt":{"en":true,"broker":"evil"},"ntp":{"en":true},
          "sync":{"recv":{"grp":1},"send":{"en":true}},"live":{"en":false}},
    "nw":{"ins":[{"ssid":"Home"}]},
    "ap":{"ssid":"x","psk":"y"},
    "ota":{"lock":false},
    "pin":"1234",
    "pixc":{"lan":"00"},
    "um":{"PixcConnect":{"settingsPin":"k"},"AudioReactive":{"sync":{"mode":2}}},
    "hw":{"led":{"maxpwr":4000},"btn":{"ins":[{"type":2,"pin":[4]}],"tt":32},"relay":{"pin":5},
          "ir":{"pin":6,"type":1}}
  })"));
  sanitizeLanCfg(doc.as<JsonObject>());
  JsonObject r = doc.as<JsonObject>();
  // All of "if" goes (security audit 2026-10-20): the broker, and the UDP sync notifier, which a
  // member could switch on before being removed and then drive the light with after the rotation.
  CHECK(r["if"].isNull());
  CHECK(r["nw"]["ins"][0]["ssid"] == "Home");       // the app's "change network" stays
  CHECK(r["ap"].isNull() && r["ota"].isNull() && r["pin"].isNull() && r["pixc"].isNull());
  CHECK(r["um"]["PixcConnect"].isNull());
  CHECK(r["um"]["AudioReactive"]["sync"]["mode"] == 2);
  CHECK(r["id"]["name"] == "Desk");
  CHECK(r["hw"]["led"]["maxpwr"] == 4000);          // the app's strip settings stay
  // No button, relay or IR receiver from the LAN: a fake touch button could be "released" on demand
  // into WLED's 10 s factory reset, and pairing v2 has no LAN reset.
  CHECK(r["hw"]["btn"].isNull() && r["hw"]["relay"].isNull() && r["hw"]["ir"].isNull());
  // A non-object "hw" does not crash either.
  DynamicJsonDocument d3(128);
  CHECK(!deserializeJson(d3, R"({"hw":7,"on":true})"));
  sanitizeLanCfg(d3.as<JsonObject>());
  CHECK(d3["on"] == true && d3["hw"] == 7);
  // A body without any of them is left alone, and a non-object "if" or "um" does not crash.
  DynamicJsonDocument d2(256);
  CHECK(!deserializeJson(d2, R"({"if":5,"um":"x","bri":9})"));
  sanitizeLanCfg(d2.as<JsonObject>());
  CHECK(d2["bri"] == 9);
}

// What a state write may not do (security audit 2026-10-20): no "win", no notifier switches, and no
// reboot from a stored preset.
static void testSanitizeState() {
  const char* body = R"({"on":true,"bri":80,"win":"RN=1&SN=1&RB","rb":true,
    "udpn":{"send":true,"sgrp":1,"rgrp":1,"nn":true},"seg":[{"fx":9}]})";
  DynamicJsonDocument req(1024);
  CHECK(!deserializeJson(req, body));
  sanitizeState(req.as<JsonObject>(), false);
  CHECK(req["win"].isNull());
  CHECK(req["udpn"]["send"].isNull() && req["udpn"]["sgrp"].isNull() && req["udpn"]["rgrp"].isNull());
  CHECK(req["udpn"]["nn"] == true);                 // "do not notify" is harmless and stays
  CHECK(req["rb"] == true);                         // a request may still reboot the light
  CHECK(req["on"] == true && req["bri"] == 80 && req["seg"][0]["fx"] == 9);
  // The same body as a stored preset: no reboot either, so a boot preset cannot loop.
  DynamicJsonDocument pre(1024);
  CHECK(!deserializeJson(pre, body));
  sanitizeState(pre.as<JsonObject>(), true);
  CHECK(pre["rb"].isNull() && pre["win"].isNull() && pre["udpn"]["rgrp"].isNull());
  CHECK(pre["on"] == true && pre["seg"][0]["fx"] == 9);
  // A non-object "udpn" does not crash, and an empty body stays empty.
  DynamicJsonDocument odd(128);
  CHECK(!deserializeJson(odd, R"({"udpn":3,"bri":5})"));
  sanitizeState(odd.as<JsonObject>(), true);
  CHECK(odd["bri"] == 5);
  DynamicJsonDocument none(64);
  CHECK(!deserializeJson(none, "{}"));
  sanitizeState(none.as<JsonObject>(), true);
  CHECK(none.as<JsonObject>().size() == 0);
}

// D465: a stored preset may not save, delete or remove files.
static void testSanitizeStatePersists() {
  const char* body = R"({"psave":7,"pdel":3,"rmcpal":0,"n":"x","on":true,"bri":9})";
  DynamicJsonDocument req(512);
  CHECK(!deserializeJson(req, body));
  sanitizeState(req.as<JsonObject>(), false);
  CHECK(req["psave"] == 7 && req["pdel"] == 3 && req.containsKey("rmcpal"));   // a request still may
  DynamicJsonDocument pre(512);
  CHECK(!deserializeJson(pre, body));
  sanitizeState(pre.as<JsonObject>(), true);
  CHECK(pre["psave"].isNull() && pre["pdel"].isNull() && !pre.containsKey("rmcpal"));
  CHECK(pre["on"] == true && pre["bri"] == 9 && pre["n"] == "x");
}

// D465: which state writes touch the filesystem (WLED's own ranges).
static void testPersistsState() {
  auto persists = [](const char* json) {
    DynamicJsonDocument d(512);
    if (deserializeJson(d, json)) return false;
    return persistsState(d.as<JsonObject>());
  };
  CHECK(!persists(R"({"on":true,"bri":128,"seg":[{"fx":9}]})"));
  CHECK(!persists(R"({"ps":4})"));                    // applying a preset reads only
  CHECK(!persists(R"({"psave":0})"));
  CHECK(persists(R"({"psave":1})"));
  CHECK(persists(R"({"psave":250,"n":"Evening","ib":true})"));
  CHECK(!persists(R"({"psave":251})"));               // WLED ignores 251-255 for psave
  CHECK(!persists(R"({"psave":255})"));               // the temporary preset stays in RAM
  CHECK(!persists(R"({"psave":300})"));               // out of uint8_t: 0, ignored by WLED too
  CHECK(persists(R"({"psave":"5"})"));                // ArduinoJson converts it, as WLED's read does
  CHECK(persists(R"({"pdel":12})"));
  CHECK(!persists(R"({"pdel":251})"));
  CHECK(persists(R"({"rmcpal":0})"));
  CHECK(persists(R"({"rmcpal":true})"));
  CHECK(persists(R"({"psave":5,"playlist":{"ps":[1,2],"dur":[10,10]}})"));
}

// D465: the flash write budget.
static void testWriteBudget() {
  WriteBudget b(kCfgWriteBurst, kCfgWriteRefillMs);
  uint64_t t = 1000, wait = 99;
  // Ordinary use: three saves at once go straight through.
  for (int i = 0; i < kCfgWriteBurst; i++) CHECK(b.take(t, &wait) && wait == 0);
  // The fourth waits for the next token, and says how long.
  CHECK(!b.take(t, &wait) && wait == kCfgWriteRefillMs);
  CHECK(!b.take(t + 10000, &wait) && wait == kCfgWriteRefillMs - 10000);
  CHECK(b.take(t + kCfgWriteRefillMs, &wait) && wait == 0);
  CHECK(!b.take(t + kCfgWriteRefillMs + 1));
  // A sender that never stops gets one write per refill period, no more: a try every millisecond
  // for ten minutes buys the burst and then one write at each 30 s mark (19 of them).
  {
    WriteBudget h(kCfgWriteBurst, kCfgWriteRefillMs);
    int writes = 0;
    for (uint64_t ms = 0; ms < 600000; ms++) if (h.take(5000 + ms)) writes++;
    CHECK(writes == kCfgWriteBurst + 19);
  }
  // Quiet time refills the burst but banks no more than it.
  CHECK(b.tokens(t + 10 * 60 * 1000) == kCfgWriteBurst);
  CHECK(b.tokens(t + 60 * 60 * 1000) == kCfgWriteBurst);
  // A clock that goes back does not mint tokens.
  {
    WriteBudget c(2, 1000);
    CHECK(c.take(50000) && c.take(50000) && !c.take(50000));
    CHECK(!c.take(40000));
    CHECK(!c.take(40999) && c.take(41000));
  }
  // The preset budget: five at once, then one per 30 s.
  WriteBudget p(kPresetWriteBurst, kPresetWriteRefillMs);
  int ok = 0;
  for (int i = 0; i < 20; i++) if (p.take(7000)) ok++;
  CHECK(ok == kPresetWriteBurst);
  CHECK(p.take(7000 + kPresetWriteRefillMs) && !p.take(7000 + kPresetWriteRefillMs));
}

// D465: request bodies decided from the headers.
static void testClassifyBody() {
  const BodyRoute N = BodyRoute::Normal, S = BodyRoute::SignedWrite, D = BodyRoute::Discard;
  // The signed JSON writes the gate pre-checks.
  CHECK(classifyBody(true, "/json", "application/json", 40, false) == S);
  CHECK(classifyBody(true, "/json/state", "application/json", 40, false) == S);
  CHECK(classifyBody(true, "/json/cfg", "APPLICATION/JSON", 16383, false) == S);   // case, as the handler
  CHECK(classifyBody(true, "/json/pixc/anything", "application/json", 10, false) == S);
  // Not buffered by anyone, or not this gate's to judge.
  CHECK(classifyBody(true, "/json", "application/json", 0, false) == N);          // no body
  CHECK(classifyBody(true, "/json", "application/json", 16384, false) == N);      // never copied (413)
  CHECK(classifyBody(true, "/json/pixc/pair", "application/json", 300, false) == N);  // hotspot, 1 KB
  CHECK(classifyBody(true, "/json/pixc/pair/x", "application/json", 300, false) == N);
  CHECK(classifyBody(true, "/jsonx", "application/json", 40, false) == N);        // not the JSON API
  CHECK(classifyBody(true, "/foo", "application/json", 40, false) == N);          // 404, body unread
  CHECK(classifyBody(false, "/json/state", "application/json", 40, false) == N);  // GET: no JSON handler
  CHECK(classifyBody(true, "/json", "application/octet-stream", 40, false) == N);
  CHECK(classifyBody(true, "/json", "", 40, false) == N);
  CHECK(classifyBody(true, nullptr, "application/json", 40, false) == N);
  // Bodies WLED would parse into parameters, on any path: dropped unread.
  CHECK(classifyBody(true, "/json", "application/x-www-form-urlencoded", 40, false) == D);
  CHECK(classifyBody(false, "/json/state", "application/x-www-form-urlencoded", 100000, false) == D);
  CHECK(classifyBody(true, "/anything", "text/plain", 5, false) == D);
  CHECK(classifyBody(true, "/upload", "multipart/form-data", 9000, true) == D);
  CHECK(classifyBody(true, "/json/pixc/pair", "application/x-www-form-urlencoded", 50, false) == D);
  CHECK(classifyBody(true, "/x", "application/x-www-form-urlencoded", 0, false) == N);   // no body
  CHECK(classifyBody(true, "/json", nullptr, 40, false) == N);
}

